import { AxisScale } from '@visx/axis';

import { isLogScale } from '../../../functions/detect-scale.js';
import {
  tickValueFormatter,
  formatValue,
} from '../../../functions/format-value.js';
import { ChartUnit } from '../../../types/chart-unit.js';
import { Formatter } from '../../../types/formatter.js';

const sanitizeEpsilonValue = (value: number) =>
  value === Number.EPSILON ? 0 : value;

/**
 * Gets y-axis tick formatter depending on the type of scale.
 *
 * As the log scale doesn't support zero or negative values, the smallest number is EPSILON, and it must be sanitized into a 0 to represent better human-readable ticks.
 *
 * @param scale - axis scale
 * @param unit - axis unit
 * @param formatter - axis formatter
 * @param numTicks - proposed number of ticks
 * @param precision - tick values precision
 *
 * @returns formatter
 */
export function getYAxisTickFormatter(
  scale: AxisScale,
  unit: ChartUnit,
  formatter?: Formatter,
  numTicks?: number,
  precision?: number,
): Formatter {
  const valueFormatter = formatter ?? formatValue;
  const logFormatter = (value: number) => {
    // d3's default formatter for log scale automatically formats non-major values to empty string
    // eslint-disable-next-line @typescript-eslint/ban-ts-comment
    // @ts-expect-error - @visx AxisScale does not have tickFormat method
    const isMajorValue = scale.tickFormat(numTicks)(value) !== '';
    const nonEpsilonValue = sanitizeEpsilonValue(value);

    return isMajorValue ? valueFormatter(nonEpsilonValue, unit, precision) : '';
  };
  const linearFormatter = (value: number) =>
    valueFormatter(value, unit, precision);
  const yAxisTickFormatter = isLogScale(scale) ? logFormatter : linearFormatter;

  return tickValueFormatter(yAxisTickFormatter, unit);
}
